// Generates src/schema.d.ts from the committed openapi.json snapshot.
//
//   node scripts/schema.mjs           write src/schema.d.ts
//   node scripts/schema.mjs --check   exit 1 if src/schema.d.ts is stale (CI)
import { readFile, writeFile } from 'node:fs/promises'
import openapiTS, { astToString } from 'openapi-typescript'

const SNAPSHOT = new URL('../openapi.json', import.meta.url)
const TARGET = new URL('../src/schema.d.ts', import.meta.url)
const HEADER =
  '// GENERATED by scripts/schema.mjs from openapi.json. Do not edit; run `pnpm generate`.\n\n'

const document = JSON.parse(await readFile(SNAPSHOT, 'utf8'))
const generated = HEADER + astToString(await openapiTS(document))

if (process.argv.includes('--check')) {
  const current = await readFile(TARGET, 'utf8').catch(() => '')
  if (current !== generated) {
    console.error(
      'src/schema.d.ts is stale: run `pnpm --filter @mentoragent/mentor-agent-contracts generate`.',
    )
    process.exit(1)
  }
  console.log('src/schema.d.ts matches openapi.json')
} else {
  await writeFile(TARGET, generated)
  console.log('wrote src/schema.d.ts')
}
